var TYPES = { html: "text/html; charset=utf-8", js: "text/javascript; charset=utf-8", css: "text/css; charset=utf-8", svg: "image/svg+xml", json: "application/json; charset=utf-8" };
var PAGES = { "/signin": "/signin.html", "/welcome": "/welcome.html", "/account": "/account.html", "/admin": "/admin.html" };
var SECURITY = {
  "x-content-type-options": "nosniff",
  "referrer-policy": "no-referrer",
  "x-frame-options": "DENY",
  "content-security-policy": "frame-ancestors 'none'; base-uri 'none'; object-src 'none'",
  "strict-transport-security": "max-age=31536000",
  "permissions-policy": "camera=(), microphone=(), geolocation=(), payment=()"
};
async function servePage(path, env, url) {
  const file = PAGES[path] || (path.startsWith("/static/") ? path.slice(7) : "");
  const text2 = file && ASSETS[file];
  if (text2 === void 0 || !file) return null;
  const ext = file.split(".").pop();
  const cache = ext === "html" ? "no-store" : "public, max-age=3600";
  return new Response(text2, { headers: Object.assign({ "content-type": TYPES[ext] || "text/plain; charset=utf-8", "cache-control": cache }, SECURITY) });
}

