  if (!previous || typeof previous !== "object" || !errors.length) throw new Fail(400, "format", "\u05D7\u05E1\u05E8\u05D9\u05DD \u05E4\u05E8\u05D8\u05D9\u05DD \u05DC\u05EA\u05D9\u05E7\u05D5\u05DF");
